def post(r1, c1, r2, c2, r):
    same_square = And(r1 == r2, c1 == c2)
    on_diagonal = Or(r1 - c1 == r2 - c2, r1 + c1 == r2 + c2)
    same_color = ((r1 + c1) - (r2 + c2)) % 2 == 0
    return And(
        Implies(same_square, r == 0),
        Implies(And(Not(same_square), on_diagonal), r == 1),
        Implies(And(Not(on_diagonal), same_color), r == 2),
        Implies(Not(same_color), r == -1),
    )
